mkdir -p /tmp/sms-gate-test && cat > /tmp/sms-gate-test/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { checkSms } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g1-3/bot.mjs";

const U = (tz) => ({ id: "u_1", phone: "+13125550142", timezone: tz });
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log("ok -", name); };

// Independent wall-clock reader for property checks.
const hourIn = (ms, tz) => Number(new Intl.DateTimeFormat("en-US", { timeZone: tz, hour: "numeric", hourCycle: "h23" }).format(new Date(ms)));
const inWindow = (ms, tz) => { const h = hourIn(ms, tz); return h >= 9 && h < 20; };

ok("Chicago open midday", () => {
  const r = checkSms(U("America/Chicago"), at("2026-10-23T15:00:00Z")); // 10:00 CDT
  assert.equal(r.allowed, true); assert.equal(r.nextAllowedAt, null); assert.equal(typeof r.reason, "string");
});
ok("Chicago 21:00 local held, next 09:00 next day", () => {
  const r = checkSms(U("America/Chicago"), at("2026-10-23T02:00:00Z")); // 21:00 CDT Oct 22
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), "2026-10-23T14:00:00.000Z");
});
ok("Chicago 08:59 held, 09:00 allowed, 19:59 allowed, 20:00 held", () => {
  assert.equal(checkSms(U("America/Chicago"), at("2026-10-23T13:59:00Z")).allowed, false); // 08:59
  assert.equal(checkSms(U("America/Chicago"), at("2026-10-23T14:00:00Z")).allowed, true);  // 09:00
  assert.equal(checkSms(U("America/Chicago"), at("2026-10-24T00:59:00Z")).allowed, true);  // 19:59
  const r = checkSms(U("America/Chicago"), at("2026-10-24T01:00:00Z")); // 20:00
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), "2026-10-24T14:00:00.000Z");
});
ok("Kolkata half-hour offset: 08:59 held -> 09:00 IST = 03:30Z", () => {
  const held = checkSms(U("Asia/Kolkata"), at("2026-10-23T03:29:00Z")); // 08:59 IST
  assert.equal(held.allowed, false); assert.equal(held.nextAllowedAt.toISOString(), "2026-10-23T03:30:00.000Z");
  assert.equal(checkSms(U("Asia/Kolkata"), at("2026-10-23T03:30:00Z")).allowed, true);
});
ok("Kathmandu +05:45 boundary", () => {
  const r = checkSms(U("Asia/Kathmandu"), at("2026-10-23T03:14:00Z")); // 08:59 NPT
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), "2026-10-23T03:15:00.000Z");
});
ok("US fall-back day (Nov 1 2026, New York) next opening crosses DST", () => {
  const r = checkSms(U("America/New_York"), at("2026-11-01T04:30:00Z")); // 00:30 EDT
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), "2026-11-01T14:00:00.000Z"); // 09:00 EST
});
ok("US spring-forward day (Mar 8 2026, New York)", () => {
  const r = checkSms(U("America/New_York"), at("2026-03-08T03:00:00Z")); // 22:00 EST Mar 7
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), "2026-03-08T13:00:00.000Z"); // 09:00 EDT
});
ok("null timezone -> held, no next time", () => {
  const r = checkSms(U(null), at("2026-10-23T15:00:00Z"));
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt, null); assert.ok(r.reason.length > 0);
});
ok("unrecognised timezone -> held, no next time", () => {
  for (const tz of ["Mars/Olympus", "", "   ", 42, undefined]) {
    const r = checkSms(U(tz), at("2026-10-23T15:00:00Z"));
    assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt, null);
  }
  assert.equal(checkSms(undefined, at("2026-10-23T15:00:00Z")).allowed, false);
});
ok("invalid now -> held", () => {
  const r = checkSms(U("America/Chicago"), new Date("nope"));
  assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt, null);
  assert.equal(checkSms(U("America/Chicago"), "2026-10-23").allowed, false);
});
ok("UTC zone and Etc zone work", () => {
  assert.equal(checkSms(U("UTC"), at("2026-10-23T10:00:00Z")).allowed, true);
  assert.equal(checkSms(U("Etc/GMT+5"), at("2026-10-23T14:00:00Z")).allowed, true); // 09:00 at UTC-5
});
ok("machine TZ does not matter (TZ env ignored)", () => {
  // Same instant, same zone, result must not depend on process TZ; checked by running with TZ set in shell below.
  const r = checkSms(U("Europe/Berlin"), at("2026-10-23T07:30:00Z")); // 09:30 CEST
  assert.equal(r.allowed, true);
});

// Property sweep: every held result's nextAllowedAt is (a) inside window,
// (b) not earlier than any minute in between being open, (c) never more than 1 day away.
ok("property sweep: nextAllowedAt is the first open minute, for many zones and instants", () => {
  const zones = ["America/Chicago", "America/New_York", "America/Los_Angeles", "America/Anchorage", "Pacific/Honolulu", "Asia/Kolkata", "Asia/Kathmandu", "Australia/Lord_Howe", "Europe/London", "UTC"];
  const start = Date.UTC(2026, 2, 6);
  let checked = 0;
  for (const tz of zones) {
    for (let t = start; t < start + 40 * 86400000; t += 47 * 60000) { // 47-min step, crosses DST in March and November
      const r = checkSms(U(tz), new Date(t));
      if (r.allowed) { assert.ok(inWindow(t, tz), `allowed outside window ${tz} ${new Date(t).toISOString()}`); continue; }
      const nx = r.nextAllowedAt.getTime();
      assert.ok(nx > t, "next must be in the future");
      assert.ok(nx - t <= 86400000, `next too far ${tz} ${new Date(t).toISOString()}`);
      assert.ok(inWindow(nx, tz), `next not open ${tz} ${new Date(t).toISOString()} -> ${new Date(nx).toISOString()}`);
      assert.ok(inWindow(nx - 60000, tz) === false, "one minute before next must be closed");
      for (let m = t; m < nx; m += 60000) assert.ok(!inWindow(m, tz), `open minute before next ${tz} ${new Date(m).toISOString()}`);
      checked++;
    }
  }
  console.log("   checked", checked, "held results");
});

console.log(`\n${n} groups passed`);
EOF
